import {sources,companies,prepTasks,phases,makeWeeks,PLAN_START,PLAN_END,RESEARCH_DATE} from './career-data.mjs';
import {latestCareer,validateCareerEntries,validateCareerProfile} from './career-domain.mjs';
export function createCareer(ctx){
const {esc,icon,addDays,dateLabel}=ctx, weeks=makeWeeks(ctx.seed);
let selectedApplication=null;
const state=()=>ctx.state(), profile=()=>state().careerProfile, entries=()=>state().careerEntries;
const done=t=>latestCareer(entries(),'task',t.id)?.status==='Done';
const week=()=>weeks[profile().week-1];
const link=(url,title)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗</a>`;
const sourceLink=id=>{const s=sources.find(s=>s.id===id);return link(s.url,s.title)};
const heading=(k,h,p)=>`<div class="page-heading"><div><span class="eyebrow">${k}</span><h1>${h}</h1><p>${p}</p></div></div>`;
const metric=(n,label,sub)=>`<article class="metric card"><div class="metric-value">${n}</div><h3>${label}</h3><p>${sub}</p></article>`;
const lastApplications=()=>[...new Set(entries().filter(e=>e.kind==='application').map(e=>e.itemId))].map(id=>latestCareer(entries(),'application',id));
const tasksFor=track=>prepTasks.filter(t=>t.track===track);
function taskCard(t){const e=latestCareer(entries(),'task',t.id);return `<article class="career-task card"><div class="task-top"><span class="eyebrow">${t.id} · WEEK ${t.week}</span><span class="badge ${done(t)?'green':'neutral'}">${esc(e?.status||'Not started')}</span></div><h3>${esc(t.title)}</h3><p>${esc(t.prompt)}</p><div class="done-definition"><strong>Evidence to keep</strong><p>${esc(t.done)}</p></div><button class="btn outline" data-prep="${t.id}">${e?'Update notes':'Start this task'} ${icon('arrow',16)}</button></article>`;}
function today(){
const sum=ctx.summary(),w=week(),next=w.ids.map(id=>ctx.seed.problems.find(p=>p.id===id)).find(p=>!sum.reviews[p.id].everSolved)||sum.next;
const day=Math.max(0,Math.ceil((Date.parse(PLAN_END)-Date.parse(ctx.today()))/86400000));
const total=prepTasks.filter(done).length,mocks=entries().filter(e=>e.kind==='mock'),a=lastApplications(),budget=profile().dailyMinutes;
const review=Math.round(budget/6),dsa=Math.round(budget*7/12),other=budget-review-dsa;
return heading('GOOGLE FIRST · INDIA · JAVA','A big goal. A clear next step.','Your campus-to-career workspace. Build skill, prove it, and keep applying.')
+`<div class="mission-grid"><section class="mission-hero"><div><span class="hero-chip">THE MARCH MISSION / 2027</span><h2>Prepare with purpose.<br><span>Earn your next opportunity.</span></h2><p>DSA is the engine. Communication, projects and fundamentals make the preparation complete.</p><div class="hero-actions">${state().settings.paused?'<a class="btn lime" href="#settings">Resume your plan</a>':next?`<button class="btn lime" data-task="${next.id}">Start a Java problem →</button>`:'<a class="btn lime" href="#reviews">Revisit a pattern →</a>'}<a class="hero-link" href="#roadmap">See the 22-week plan ↗</a></div></div><div class="mission-orbit" aria-label="March preparation checkpoint"><span>CHECKPOINT</span><strong>MAR<br>31</strong><span>${day?day+' days to prepare':'Review your next phase'}</span><small>Not a hiring deadline</small></div></section><section class="card focus-plan"><span class="eyebrow">YOUR DAILY RHYTHM</span><h2>${budget}<small> min</small></h2><div class="time-bar"><i></i><i></i><i></i></div><p><b>${dsa} min</b> DSA + explain aloud</p><p><b>${review} min</b> Spaced revision</p><p><b>${other} min</b> Rotate the supporting track</p><a href="#profile" class="text-link">${profile().daysPerWeek} study days / week · Adjust →</a></section></div>
<div class="metrics-grid career-metrics">${metric(sum.solved+'/96','Core tasks solved','Understanding before volume')}${metric(sum.retained,'Patterns retained','Successful later-day revisits')}${metric(mocks.length,'Mocks reviewed','Feedback saved, not just a timer')}${metric(total+'/'+prepTasks.length,'Supporting milestones','Project · CS · stories · career')}</div>
<div class="section-heading"><div><h2>This week’s mission</h2><p>Week ${w.week} · ${esc(w.title)}</p></div><a href="#roadmap" class="text-link">Change week →</a></div>
<div class="mission-lower"><section class="card mission-checklist"><span class="eyebrow">YOUR NEXT ACTIONS</span>${state().settings.paused?'<p>New-task suggestions are paused. Use the revision queue or browse the curriculum manually.</p>':`<a class="mission-row" href="#practice"><span class="step-number">01</span><div><strong>Practise the core patterns</strong><p>${w.ids.length?'Up to six new tasks this week. Carry unfinished work forward.':'Choose unseen mixed problems; redo weak patterns.'}</p></div>→</a><a class="mission-row" href="#reviews"><span class="step-number">02</span><div><strong>${sum.due.length} revisions ready</strong><p>Start with a blank file. Explain time and space.</p></div>→</a><a class="mission-row" href="#${w.week%2?'cs':'project'}"><span class="step-number">03</span><div><strong>${w.week%2?'Strengthen your fundamentals':'Build your Java project'}</strong><p>${w.mock}. Replace a DSA block; do not add extra hours.</p></div>→</a>`}</section>
<section class="card weekly-rhythm"><span class="eyebrow">KEEP THE OTHER TRACKS MOVING</span><h3>A week you can repeat.</h3><p><b>Mon / Thu</b> CS fundamentals + light design</p><p><b>Tue / Fri</b> One Java project</p><p><b>Wed</b> Stories + resume</p><p><b>Sat</b> Mock, feedback and openings</p><p><b>Sun</b> Rest or optional catch-up</p><a href="#applications" class="text-link">Track opportunities →</a></section></div>
<div class="note-banner"><strong>Apply alongside preparation.</strong> March is your readiness checkpoint, not an application opening date. Review real postings weekly. ${!profile().graduation?'<a href="#profile">Add your graduation date →</a>':''}</div>
<div class="section-heading"><div><h2>Prepare for the whole conversation</h2><p>Six connected tracks. A shared foundation for Google, Microsoft and other eligible roles.</p></div></div>
<div class="track-grid">${[['practice','Java DSA','96 core + 60 optional','code'],['cs','CS fundamentals','OS · DBMS · networks · OOP','book'],['project','Project lab','One project you can defend','code'],['stories','Story bank','Real examples, clearly told','history'],['mocks','Mock studio','Practise, score, repair','clock'],['interviews','Company playbooks','Sources and recruiter checks','map']].map(([id,n,d,ic])=>`<a href="#${id}" class="card track-card"><span class="icon-tile sage">${icon(ic)}</span><h3>${n}</h3><p>${d}</p><span>Open track ↗</span></a>`).join('')}</div>`;
}
function plan(){return heading('26 OCT 2026 → 31 MAR 2027','Your 22-week runway.','Our preparation plan, not a company hiring requirement. Six new core tasks per week for 16 weeks; then six weeks of rehearsal.')
+`<div class="note-banner"><strong>Readiness review:</strong> across three recent unseen coding mocks, aim to explain a sound approach, implement it, test edge cases and analyze complexity within 45 minutes. Revisit weak patterns independently on a later day. Also rehearse a five-minute project walkthrough and six truthful behavioral stories. These are practice targets, not employer cutoffs.</div><div class="phase-strip">${phases.map(p=>`<div><span>WEEKS ${p.weeks}</span><h3>${p.name}</h3><p>${p.detail}</p></div>`).join('')}</div><div class="note-banner"><strong>Use evidence to set the pace.</strong> If you cannot explain and redo this week’s patterns, carry them forward and trim optional work. Exam week: 30–45 minutes of revision on study days. No catch-up debt. March 29–31 is buffer time.</div><div class="plan-list">${weeks.map(w=>`<details class="card plan-week" ${w.week===profile().week?'open':''}><summary><span class="week-index">${String(w.week).padStart(2,'0')}</span><div><span class="eyebrow">${dateLabel(addDays(PLAN_START,(w.week-1)*7))} – ${dateLabel(addDays(PLAN_START,w.week*7-1))}</span><h3>${esc(w.title)}</h3></div><span class="badge ${w.week===profile().week?'green':'neutral'}">${w.ids.length?w.ids.filter(id=>ctx.summary().reviews[id].everSolved).length+'/'+w.ids.length:'Rehearsal'}</span></summary><div class="plan-body"><button class="btn outline" data-career-week="${w.week}">Make this my focus</button><p>${esc(w.mock)}. Review feedback the same day.</p><div class="plan-problems">${w.ids.map(id=>`<button data-task="${id}">${ctx.summary().reviews[id].everSolved?'✓':'○'} ${esc(ctx.seed.problems.find(p=>p.id===id).title)} <small>${id}</small></button>`).join('')||'<p>Use mixed, unseen practice; log attempts in DSA practice and feedback in Mock studio.</p>'}</div><p><b>Supporting milestones:</b> ${w.parallel.map(id=>`<button class="text-link" data-prep="${id}">${esc(prepTasks.find(t=>t.id===id).title)}</button>`).join(' · ')||'Continue the unfinished milestone in each supporting track.'}</p><p><b>Light design:</b> ${w.week<=12?`<button class="text-link" data-design-week="${w.week}">Design notebook ${w.week}</button>`:'Revisit a project design or explain a tradeoff. Advanced distributed systems are optional unless your interview requires them.'}</p>${w.week===14?'<p>Optional after graph basics: explore weighted shortest paths (module U). No company frequency claim is attached to these exercises.</p>':''}</div></details>`).join('')}</div>`;}
function interviews(){return heading('RESEARCH CHECKED · 26 OCT 2026','Know what you are preparing for.','Official sources where accessible. Your recruiter’s instructions take precedence over any generic interview map.')
+`<div class="note-banner">Google is the main target; India student/early-career SWE is the scope. A fixed Google round count, exact question list or guaranteed offer is not claimed. The original DSA exercises are practice patterns, not leaked or verified company questions.</div><div class="company-list">${companies.map(c=>`<article class="card company-card"><span class="eyebrow">${c.tag}</span><h2>${c.name}</h2><h3>${c.headline}</h3><div class="round-flow">${c.stages.map((s,i)=>`<span><b>0${i+1}</b>${esc(s)}</span>`).join('')}</div><p>${esc(c.facts)}</p><div class="company-columns"><div><h4>How we prepare</h4><p>${esc(c.prepare)}</p></div><div><h4>Confirm for your role</h4><p>${esc(c.confirm)}</p></div></div><div class="source-links">${c.sourceIds.map(sourceLink).join('')}</div></article>`).join('')}</div><section class="card research-notes"><h2>What to practise in a coding round</h2><div class="round-flow">${['Clarify constraints','Explain a baseline','Choose a better approach','Code in Java','Test + analyze'].map((x,i)=>`<span><b>${i+1}</b>${x}</span>`).join('')}</div><p>Practice prompts: find a pair with a target sum; find a shortest unweighted path; maintain the largest k items in a stream; choose a DP state for minimum cost. These illustrate skills, not predictions of your actual questions.</p><p>For student roles, keep design proportional: API/data modeling, object design and your own project first. Increase distributed-systems depth when the job or recruiter calls for it.</p></section><section class="card research-notes"><h2>Source register</h2><p>Checked ${RESEARCH_DATE}. Job availability and interview formats can change. Google’s live hiring pages rendered only their shell during review; the older official video is explicitly dated above.</p>${sources.map(s=>`<p>${sourceLink(s.id)}<br><small>${esc(s.note)}</small></p>`).join('')}</section>`;}
function track(name){return heading(name.toUpperCase(),{ 'CS fundamentals':'Understand what runs beneath your code.','Project lab':'Build one project. Know it deeply.','Story bank':'Your experiences are interview material.','Career setup':'Turn preparation into opportunities.'}[name],name==='Story bank'?'Use real experiences from college, projects or teamwork. Notes stay on this machine.':'Each card has a concrete deliverable. Save evidence and session time as you work.')
+`<div class="career-task-grid">${tasksFor(name).map(taskCard).join('')}</div>`;}

const field=(label,name,value='',type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" max="1440"':''}></label>`;
const options=(values,selected)=>values.map(v=>`<option ${v===selected?'selected':''}>${esc(v)}</option>`).join('');
const finish=label=>`<p class="form-error" role="alert"></p><button class="btn primary" type="submit">${label}</button>`;
const rubric=['Clarifying','Approach','Code / structure','Testing / evidence','Communication'];
function mocks(){const list=entries().filter(e=>e.kind==='mock').slice().reverse();return heading('MOCK STUDIO','Practise the conversation, too.','Use a peer when possible. A solo rehearsal counts as practice; scores are self-assessed, not hiring predictions.')+`<div class="career-columns"><form class="card career-form" id="career-mock-form"><h2>Log a rehearsal</h2><p>Try 45 minutes for coding. Replace a normal DSA block; use the remaining time to review mistakes.</p><label>Session type<select name="status">${options(['Coding','OA practice','Behavioral','Design'])}</select></label>${field('Prompt or topic','title')}${field('Minutes spent','minutes',45,'number')}<p>Score each dimension: 0 not attempted · 1 needs help · 2 partial · 3 independent · 4 clear and consistent.</p><div class="rubric-fields">${rubric.map((r,i)=>`<label>${r}<select name="score${i}">${options(['0','1','2','3','4'],'2')}</select></label>`).join('')}</div><label>Feedback and next action<textarea name="notes" required placeholder="What broke down? Which pattern will you retry, and when?"></textarea></label>${finish('Save mock feedback')}</form><section><h2>${list.length} rehearsals logged</h2>${list.map(e=>`<article class="card session-card"><span class="eyebrow">${esc(e.localDate)} · ${esc(e.status)} · ${e.minutes} MIN</span><h3>${esc(e.title)}</h3><div class="score-chips">${e.scores.map((n,i)=>`<span>${rubric[i]} <b>${n}/4</b></span>`).join('')}</div><p class="preserve-lines">${esc(e.notes)}</p></article>`).join('')||'<div class="card session-card"><h3>Your first mock is a baseline.</h3><p>Explain one solution aloud this week. Add full timed rounds as your core patterns become familiar.</p></div>'}</section></div>`;}
function applications(){const list=lastApplications(),e=list.find(x=>x.itemId===selectedApplication);return heading('OPPORTUNITIES','Prepare. Apply. Keep moving.','Check India eligibility and actual deadlines every week. Apply when a suitable opening appears; March is your preparation checkpoint.')+`<div class="note-banner">Start with ${sourceLink('google-jobs')}. Record the exact role, required graduation dates and location from the posting. Saved links do not submit applications.</div><div class="career-columns"><form class="card career-form" id="career-application-form"><h2>${e?'Update application':'Add an opportunity'}</h2><input type="hidden" name="itemId" value="${esc(e?.itemId||'')}">${field('Company','company',e?.company)}${field('Role title','title',e?.title)}${field('Location / eligibility','location',e?.location||'India')}${field('Official role URL','url',e?.url,'url')}${field('Deadline (if published)','deadline',e?.deadline,'date')}<label>Stage<select name="status">${options(['Saved','Applied','OA','Interview','Offer','Closed'],e?.status)}</select></label>${field('Next action','nextAction',e?.nextAction)}<label>Notes<textarea name="notes">${esc(e?.notes||'')}</textarea></label>${finish('Save opportunity')}${e?'<button type="button" class="btn outline" data-new-application="true">Add another</button>':''}</form><section><h2>${list.length} opportunities</h2>${list.map(a=>`<article class="card session-card"><div class="task-top"><span class="eyebrow">${esc(a.company)}</span><span class="badge green">${esc(a.status)}</span></div><h3>${esc(a.title)}</h3><p>${esc(a.location)}${a.deadline?' · Deadline '+esc(a.deadline):''}</p><p><b>Next:</b> ${esc(a.nextAction||'Set a next action')}</p><p class="preserve-lines">${esc(a.notes)}</p><div class="source-links">${a.url?link(a.url,'Open role'):''}<button class="btn outline" data-edit-application="${esc(a.itemId)}">Update</button></div></article>`).join('')||'<div class="card session-card"><h3>Build your opportunity list.</h3><p>Track internships, graduate roles and strong alternatives to Google. Check the posting rather than assuming your year makes you eligible.</p></div>'}</section></div>`;}
function preferences(){const p=profile();return heading('YOUR PLAN','A schedule that fits college.','Default: 2 hours, six study days and one rest/buffer day. You can adjust this without losing any work.')+`<form id="career-profile-form" class="card career-form profile-form">${field('Main application country','country',p.country)}${field('Expected graduation month / year','graduation',p.graduation)}${field('Minutes per study day','dailyMinutes',p.dailyMinutes,'number')}${field('Study days per week','daysPerWeek',p.daysPerWeek,'number')}<label>Current preparation week<select name="week">${weeks.map(w=>`<option value="${w.week}" ${w.week===p.week?'selected':''}>Week ${w.week} · ${esc(w.title)}</option>`).join('')}</select></label><p>The default daily split is 70 minutes DSA, 20 minutes revision and 30 minutes supporting work. Fewer study days means a slower pace; carry unfinished work forward.</p><p>Germany can remain a later goal. An internal transfer depends on openings, company approval and eligibility; it is not assumed in this plan.</p>${finish('Save my plan')}</form>`;}
function openPrep(id){const t=prepTasks.find(t=>t.id===id),e=latestCareer(entries(),'task',id);if(!t)return;const dialog=document.querySelector('#task-dialog');dialog.innerHTML=`<div class="dialog-header"><div><span class="eyebrow">${esc(t.track)} · WEEK ${t.week}</span><h2 id="dialog-title">${esc(t.title)}</h2></div><button class="icon-button" data-action="close-dialog" aria-label="Close">${icon('close')}</button></div><form id="career-task-form" class="career-form"><input type="hidden" name="itemId" value="${id}"><p>${esc(t.prompt)}</p><div class="done-definition"><strong>Evidence to keep</strong><p>${esc(t.done)}</p></div><label>Status<select name="status">${options(['Learning','Practising','Done'],e?.status)}</select></label>${field('Minutes this session (not total)','minutes',30,'number')}<label>Notes / evidence<textarea name="notes" required>${esc(e?.notes||'')}</textarea></label><p>Keep links, examples and takeaways here. Mark Done when you can show the evidence above.</p>${finish('Save preparation session')}</form>`;dialog.showModal();}
async function submit(form){const f=new FormData(form),v=n=>String(f.get(n)||'').trim();if(form.id==='career-profile-form'){const p=validateCareerProfile({country:v('country'),graduation:v('graduation'),dailyMinutes:Number(v('dailyMinutes')),daysPerWeek:Number(v('daysPerWeek')),week:Number(v('week'))});await ctx.commit(s=>{s.careerProfile=p;s.settings.minutesPerDay=p.dailyMinutes;s.settings.daysPerWeek=p.daysPerWeek});}
else {const kind=form.id==='career-task-form'?'task':form.id==='career-mock-form'?'mock':'application',id=crypto.randomUUID();const e={id,kind,itemId:v('itemId')||id,occurredAt:new Date().toISOString(),localDate:ctx.today(),minutes:kind==='application'?0:Number(v('minutes')),notes:v('notes'),title:kind==='task'?prepTasks.find(t=>t.id===v('itemId')).title:v('title'),status:v('status')};if(kind!=='task'&&!e.title)throw Error('Add a title before saving.');if(kind==='mock')e.scores=rubric.map((_,i)=>Number(v('score'+i)));if(kind==='application'){for(const k of ['company','url','deadline','nextAction','location'])e[k]=v(k);if(!e.company)throw Error('Add the company name.');}validateCareerEntries([e]);await ctx.commit(s=>s.careerEntries.push(e));selectedApplication=null;}
ctx.saved();ctx.toast('Saved on this device.');}
async function handleClick(el){if(el.dataset.prep){if(!ctx.discard())return true;openPrep(el.dataset.prep);return true;}if(el.dataset.careerWeek){await ctx.commit(s=>s.careerProfile.week=Number(el.dataset.careerWeek));ctx.refresh();ctx.toast('Your focus week is updated.');return true;}if(el.dataset.editApplication||el.dataset.newApplication){if(!ctx.discard())return true;selectedApplication=el.dataset.editApplication||null;ctx.refresh();return true;}return false;}
return {views:{today,roadmap:plan,interviews,cs:()=>track('CS fundamentals'),project:()=>track('Project lab'),stories:()=>track('Story bank'),career:()=>track('Career setup'),mocks,applications,profile:preferences},handleClick,submit};
}
